{
  "status": "SUPPORTED",
  "task_summary": "Identify fastening components, perform fastening, place tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The object or assembly that needs to be secured.",
        "required_count": 1
      ,
      "binding_policy": "SHARED",
      "candidate_categories": ["assembly", "part", "device"],
      "required_properties": ["needs_fastening"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "Parts like screws, bolts, or clips that secure the target.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "clip", "nut"],
        "required_properties": ["compatible", "removable"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to drive the component into place.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["screwdriver", "wrench", "pliers"],
        "required_properties": ["functional"]
      },
      {
        "id": "workbench",
        "entity_kind": "OBJECT",
        "function": "The surface where the task takes place and tools are left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["surface"]
      },
      {
        "id": "robot_arm",
        "entity_kind": "OBJECT",
        "function": "The agent performing the identification, fastening, and placement.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["arm", "manipulator"],
        "required_properties": ["mobile", "gripper"]
      },
      {
        "id": "marked_location",
        "entity_kind": "REGION",
        "function": "The specific spot on the workbench designated for the work.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["spot", "area"],
        "required_properties": ["on_workbench"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatibility",
        "relation": "suit",
        "participant_roles": ["fastening_component", "fastening_target"],
        "required": true
      },
      {
        "id": "attachment",
        "relation": "attached_to",
        "participant_roles": ["fastening_component", "fastening_target"],
        "required": true
      },
      {
        "id": "final_state",
        "relation": "placed_on",
        "participant_roles": ["fastening_tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "identify",
        "participant_roles": ["robot_arm", "fastening_component", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "fasten",
        "participant_roles": ["robot_arm", "fastening_tool", "fastening_component", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "store_tool",
        "operation": "place",
        "participant_roles": ["robot_arm", "fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "tray_item",
          "visual_description": "Yellow and blue mechanical-looking object on the black tray on the workbench."
        }
      ],
      "fastening_component": [
        {
          "label": "tray_parts",
          "visual_description": "Small yellow and blue pieces on the black tray."
        }
      ],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden desk with drawers and a cabinet on top."
        }
      ],
      "robot_arm": [
        {
          "label": "white_arm",
          "visual_description": "White articulated robotic arm visible in foreground."
        }
      ],
      "marked_location": [
        {
          "label": "work_area",
          "visual_description": "The black tray sitting on the wooden surface."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "tall_blue_cabinet",
        "visual_description": "Tall blue storage unit with a handle, positioned behind the workbench.",
        "reason": "Closed storage structure that could contain fastening components or tools."
      },
      {
        "id": "drawers",
        "label": "table_drawers",
        "visual_description": "Two blue drawers underneath the workbench surface.",
        "reason": "Closed storage structures that could contain fastening components or tools."
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
